"""Emit diagnostic-only Java footprints; no pools, pieces or natural placement."""
from pathlib import Path
from plan_harbor_adaptation import proposals

ROOT=Path(__file__).resolve().parents[1]
TARGET=ROOT/'first_party_mods/alfheim_companion/src/main/java/com/continuityworks/alfheimcompanion/worldgen/HarborFootprintProposals.java'

def source():
    lines=['package com.continuityworks.alfheimcompanion.worldgen;','',
           '/** Generated by tools/gen_harbor_proposals.py. Read-only footprint experiments; not templates. */',
           'public final class HarborFootprintProposals {']
    for variant,parts in proposals().items():
        lines.append('    private static final HarborGeometry.Part[] '+variant.upper()+' = {')
        for p in parts:
            values=[*p['origin'],p['rotation'],*p['bounds']]
            lines.append('        new HarborGeometry.Part("'+p['name']+'", '+', '.join(map(str,values))+'),')
        lines.append('    };')
    lines+=['    public static HarborGeometry.Part[] get(String name) {','        return switch(name) {']
    for name in proposals():lines.append('            case "'+name+'" -> '+name.upper()+'.clone();')
    lines+=['            default -> null;','        };','    }','    private HarborFootprintProposals() {}','}','']
    return '\n'.join(lines)

if __name__=='__main__':
    TARGET.write_text(source(),encoding='utf-8',newline='\n')
    print('Five source-derived, diagnostic-only harbor footprints generated')
